INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (9, N'Cardiovast', N'nervastatina cálcica', N'hipolipemiante (estatina)', N'vermelha', N'comprimido 20 mg', N'caixa com 30 comprimidos');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (10, N'Tireonorm', N'levotironato de sódio', N'hormônio tireoidiano', N'vermelha', N'comprimido 50 mcg', N'caixa com 30 comprimidos');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (11, N'Ferronato', N'ferripolimaltosado', N'antianêmico (suplemento de ferro)', N'isenta', N'comprimido mastigável 100 mg', N'caixa com 30 comprimidos');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (12, N'Vitabex', N'complexo B (B1, B6, B12)', N'suplemento vitamínico', N'isenta', N'cápsula', N'frasco com 30 cápsulas');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (13, N'Ciclofem', N'etinilox + levonox', N'anticoncepcional hormonal oral combinado', N'vermelha', N'comprimido 0,03 mg + 0,15 mg', N'cartela com 21 comprimidos');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (14, N'Ansioplant', N'extrato seco de Passiflora brasiliensis', N'fitoterápico ansiolítico leve', N'isenta', N'cápsula 250 mg', N'frasco com 60 cápsulas');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (15, N'Reumaxil', N'reumexato', N'imunomodulador antirreumático (DMARD)', N'vermelha', N'comprimido 2,5 mg', N'cartela com 10 comprimidos');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (16, N'Dermatopol', N'sulfato de polidermina + bacitracina zínica', N'antibiótico tópico', N'vermelha', N'pomada dermatológica', N'bisnaga com 15 g');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (17, N'Oftalmil', N'lacrimetil 0,5%', N'lubrificante ocular (lágrima artificial)', N'isenta', N'colírio', N'frasco gotejador com 15 mL');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (18, N'Probionex', N'blend probiótico (Lactobacillus BR-1 + Bifidobacterium BR-2)', N'probiótico', N'isenta', N'sachê liofilizado', N'caixa com 10 sachês');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (19, N'Fungitrat', N'fungiderm 1%', N'antifúngico tópico', N'vermelha', N'creme dermatológico', N'bisnaga com 20 g');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (20, N'Tosseclear', N'mucoclear', N'expectorante', N'isenta', N'xarope 40 mg/mL', N'frasco com 120 mL');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (21, N'Venocalm', N'venoflav', N'flebotônico (venotônico)', N'isenta', N'comprimido 450 mg', N'caixa com 30 comprimidos');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (22, N'Insulfort', N'insulina isolenta humana recombinante', N'insulina de ação intermediária', N'vermelha', N'suspensão injetável 100 UI/mL', N'frasco-ampola com 10 mL');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (23, N'Cortiderm', N'cortisonil 1%', N'corticoide tópico de baixa potência', N'vermelha', N'creme dermatológico', N'bisnaga com 15 g');
INSERT INTO dbo.medicamento (id, nome_comercial, principio_ativo, classe_terapeutica, tarja, forma_farmaceutica, apresentacao) VALUES (24, N'Migranol', N'betanolol', N'betabloqueador (profilaxia de enxaqueca e anti-hipertensivo)', N'vermelha', N'comprimido 40 mg', N'caixa com 30 comprimidos');
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (1, N'indicacao', N'Tratamento da hipertensão arterial sistêmica (pressão alta) em adultos. Pode ser usado isoladamente ou em associação com outros anti-hipertensivos.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (1, N'posologia', N'1 comprimido de 10 mg uma vez ao dia, preferencialmente pela manhã, com ou sem alimentos. A dose pode ser ajustada pelo médico até 20 mg ao dia.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (1, N'contraindicacoes', N'Gestantes, pacientes com histórico de angioedema relacionado a anti-hipertensivos e insuficiência renal grave (clearance < 30 mL/min).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (1, N'efeitos_adversos', N'Tosse seca persistente, tontura ao levantar, dor de cabeça leve e, raramente, inchaço de lábios ou língua (angioedema).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (1, N'interacoes', N'Anti-inflamatórios (ex.: Dorfanol) podem reduzir o efeito anti-hipertensivo. Diuréticos potencializam a queda de pressão. Suplementos de potássio exigem cautela.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (1, N'advertencias', N'Monitorar potássio sérico e função renal a cada 3 meses. Não interromper o tratamento sem orientação médica, mesmo com a pressão controlada.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (2, N'indicacao', N'Diabetes mellitus tipo 2 em adultos, como auxiliar de dieta e exercícios para controle da glicemia.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (2, N'posologia', N'500 mg duas vezes ao dia, junto das refeições. Dose máxima: 2.000 mg ao dia, divididos em 3 tomadas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (2, N'contraindicacoes', N'Diabetes tipo 1, cetoacidose diabética, insuficiência renal moderada a grave e alergia a biguanidas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (2, N'efeitos_adversos', N'Desconforto gástrico, náusea, diarreia e gosto metálico na boca, geralmente transitórios nas primeiras semanas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (2, N'interacoes', N'Álcool aumenta o risco de acidose láctica. Contraste iodado (exames de imagem) exige suspensão temporária do medicamento.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (2, N'advertencias', N'Suspender 48 h antes de exames com contraste e cirurgias. Informar ao médico em caso de vômitos ou desidratação prolongada.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (3, N'indicacao', N'Alívio de dores leves a moderadas (dor de cabeça, dor muscular, dor de garganta) e redução de febre.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (3, N'posologia', N'1 comprimido de 750 mg a cada 6-8 horas, se necessário. Não exceder 3 comprimidos ao dia sem orientação médica.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (3, N'contraindicacoes', N'Doença hepática grave e hipersensibilidade conhecida ao paraxetamol.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (3, N'efeitos_adversos', N'Raros em doses recomendadas: reações de pele e, em superdose, lesão hepática grave.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (3, N'interacoes', N'Uso crônico pode potencializar anticoagulantes. Álcool aumenta o risco de toxicidade hepática.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (3, N'advertencias', N'Nunca exceder a dose máxima diária. Verificar se outros medicamentos em uso não contêm o mesmo princípio ativo, para evitar duplicidade.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (4, N'indicacao', N'Tratamento agudo de crises de enxaqueca, com ou sem aura, em adultos. Não é indicado para prevenção de crises.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (4, N'posologia', N'1 comprimido de 50 mg no início da crise. Se a dor retornar, pode repetir após 2 horas. Máximo de 2 comprimidos em 24 horas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (4, N'contraindicacoes', N'Doença arterial coronariana, histórico de AVC, hipertensão não controlada e uso recente de outros triptanos ou ergotamina.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (4, N'efeitos_adversos', N'Sensação de aperto no peito ou garganta, formigamento, sonolência e rubor facial.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (4, N'interacoes', N'Ergotamina e outros triptanos (risco de vasoconstrição excessiva). Antidepressivos serotoninérgicos exigem cautela (síndrome serotoninérgica).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (4, N'advertencias', N'Não usar mais de 10 dias por mês, para evitar cefaleia por uso excessivo de medicamento. Procurar avaliação se as crises mudarem de padrão.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (5, N'indicacao', N'Auxílio no relaxamento e na qualidade do sono em casos de insônia leve e tensão do dia a dia.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (5, N'posologia', N'1 cápsula 30 minutos antes de deitar. Não usar por mais de 4 semanas consecutivas sem avaliação.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (5, N'contraindicacoes', N'Gestantes, lactantes e crianças menores de 12 anos.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (5, N'efeitos_adversos', N'Sonolência matinal residual e, raramente, desconforto gástrico.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (5, N'interacoes', N'Potencializa o efeito de bebidas alcoólicas e de medicamentos sedativos.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (5, N'advertencias', N'Não dirigir ou operar máquinas após a ingestão. Insônia persistente por mais de um mês merece avaliação médica.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (6, N'indicacao', N'Alívio sintomático de azia, má digestão, queimação no estômago e gases.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (6, N'posologia', N'10 mL, 20 a 60 minutos após as refeições e ao deitar, até 4 vezes ao dia. Agitar antes de usar.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (6, N'contraindicacoes', N'Insuficiência renal grave (risco de acúmulo de magnésio).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (6, N'efeitos_adversos', N'Fezes amolecidas em doses altas e, raramente, cólicas leves.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (6, N'interacoes', N'Pode reduzir a absorção de antibióticos (quinolonas, tetraciclinas) e de Tireonorm: separar por pelo menos 2 horas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (6, N'advertencias', N'Sintomas que persistem por mais de 14 dias, perda de peso ou dificuldade para engolir exigem avaliação médica antes de continuar o uso.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (7, N'indicacao', N'Alívio dos sintomas de rinite alérgica (espirros, coriza, coceira nasal) e urticária.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (7, N'posologia', N'1 comprimido de 5 mg uma vez ao dia, preferencialmente no mesmo horário.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (7, N'contraindicacoes', N'Crianças menores de 6 anos (para a forma em comprimido) e hipersensibilidade ao componente.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (7, N'efeitos_adversos', N'Sonolência leve em uma minoria dos pacientes, boca seca e fadiga.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (7, N'interacoes', N'Álcool e sedativos podem intensificar a sonolência.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (7, N'advertencias', N'Embora o risco seja baixo, avaliar a sonolência individual antes de dirigir. Sintomas de alergia ocular intensa ou edema de glote exigem atendimento imediato.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (8, N'indicacao', N'Alívio rápido de broncoespasmo na asma e na DPOC (crises de falta de ar e chiado).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (8, N'posologia', N'1 a 2 jatos no início da crise. Pode repetir após 4-6 horas, se necessário. Uso frequente diário indica descontrole da doença de base.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (8, N'contraindicacoes', N'Hipersensibilidade aos componentes. Usar com cautela em arritmias cardíacas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (8, N'efeitos_adversos', N'Tremor fino nas mãos, palpitação, dor de cabeça e cãibras.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (8, N'interacoes', N'Betabloqueadores (ex.: Migranol) antagonizam o efeito broncodilatador.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (8, N'advertencias', N'Precisar de mais de 2 frascos ao mês é sinal de asma descontrolada: procurar o médico para ajustar o tratamento de manutenção.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (9, N'indicacao', N'Redução do colesterol LDL e prevenção de eventos cardiovasculares em pacientes com dislipidemia ou alto risco cardiovascular.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (9, N'posologia', N'1 comprimido de 20 mg à noite, todos os dias. A dose pode ser ajustada após 4 semanas conforme o perfil lipídico.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (9, N'contraindicacoes', N'Doença hepática ativa, gestação e lactação.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (9, N'efeitos_adversos', N'Dor muscular (mialgia), elevação discreta de enzimas hepáticas e, raramente, rabdomiólise.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (9, N'interacoes', N'Suco de toranja (grapefruit) aumenta a concentração da estatina — deve ser evitado. Macrolídeos e antifúngicos azólicos elevam o risco de miopatia.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (9, N'advertencias', N'Informar imediatamente dor muscular intensa ou urina escura. Dosar TGO/TGP antes de iniciar e em seguimento anual.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (10, N'indicacao', N'Reposição hormonal no hipotireoidismo primário.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (10, N'posologia', N'1 comprimido em jejum, 30 a 60 minutos antes do café da manhã, todos os dias. Dose individualizada por TSH.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (10, N'contraindicacoes', N'Tireotoxicose não tratada e insuficiência adrenal não corrigida.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (10, N'efeitos_adversos', N'Em dose excessiva: palpitação, insônia, perda de peso e tremores (sinais de hipertireoidismo iatrogênico).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (10, N'interacoes', N'Ventacid, Ferronato e antiácidos em geral reduzem a absorção: separar por pelo menos 4 horas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (10, N'advertencias', N'Não mudar de dose por conta própria. Reavaliar TSH 6 a 8 semanas após qualquer ajuste de dose.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (11, N'indicacao', N'Tratamento e prevenção de anemia ferropriva, incluindo na gestação (com acompanhamento médico).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (11, N'posologia', N'1 comprimido ao dia, preferencialmente longe de café, chá e leite, que prejudicam a absorção. Duração habitual: 3 a 6 meses.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (11, N'contraindicacoes', N'Hemocromatose e anemias não ferroprivas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (11, N'efeitos_adversos', N'Fezes escurecidas (esperado e inofensivo), constipação e desconforto gástrico.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (11, N'interacoes', N'Reduz a absorção de Tireonorm e de antibióticos quinolonas: separar os horários.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (11, N'advertencias', N'Manter fora do alcance de crianças: superdose de ferro é perigosa em pediatria. Anemia sem resposta em 4 semanas exige investigação.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (12, N'indicacao', N'Suplementação de vitaminas do complexo B em casos de deficiência comprovada ou aumento de necessidade.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (12, N'posologia', N'1 cápsula ao dia, junto a uma refeição.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (12, N'contraindicacoes', N'Hipersensibilidade aos componentes da fórmula.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (12, N'efeitos_adversos', N'Urina amarela intensa (riboflavina, inofensivo) e, raramente, náusea.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (12, N'interacoes', N'Sem interações clinicamente relevantes nas doses recomendadas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (12, N'advertencias', N'Suplemento não substitui alimentação equilibrada. Formigamento persistente pode indicar excesso de B6 com uso prolongado.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (13, N'indicacao', N'Prevenção da gravidez. Pode auxiliar na regularização do ciclo menstrual.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (13, N'posologia', N'1 comprimido ao dia, no mesmo horário, por 21 dias, seguidos de 7 dias de pausa.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (13, N'contraindicacoes', N'História de trombose, enxaqueca com aura, tabagismo em mulheres acima de 35 anos, câncer de mama e doença hepática ativa.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (13, N'efeitos_adversos', N'Náusea nos primeiros ciclos, sensibilidade mamária, alterações de humor e escape de sangramento.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (13, N'interacoes', N'Antibióticos rifampicina-like e anticonvulsivantes reduzem a eficácia. Vômitos ou diarreia intensa até 4 h após a ingestão comprometem a absorção.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (13, N'advertencias', N'Não protege contra ISTs. Dor intensa na panturrilha, falta de ar súbita ou dor de cabeça incomum e intensa exigem suspensão e avaliação imediata.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (14, N'indicacao', N'Alívio dos sintomas de ansiedade leve e irritabilidade do cotidiano.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (14, N'posologia', N'1 cápsula duas vezes ao dia. Não usar por mais de 3 meses sem avaliação.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (14, N'contraindicacoes', N'Gestantes e crianças menores de 12 anos.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (14, N'efeitos_adversos', N'Sonolência em doses altas e, raramente, tontura.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (14, N'interacoes', N'Pode somar efeito sedativo com álcool, Somnivale e medicamentos sedativos.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (14, N'advertencias', N'Ansiedade que interfere na vida diária, com crises de pânico ou pensamentos negativos, requer avaliação profissional — o fitoterápico não substitui esse cuidado.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (15, N'indicacao', N'Artrite reumatoide ativa em adultos, como modificador da doença.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (15, N'posologia', N'Dose semanal única (ex.: 7,5 mg uma vez por semana), sempre no mesmo dia da semana. NUNCA usar diariamente. Suplementar ácido fólico conforme prescrição.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (15, N'contraindicacoes', N'Gestação, doença hepática ou renal grave, imunossupressão importante e alcoolismo.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (15, N'efeitos_adversos', N'Náusea no dia da tomada, aftas, elevação de enzimas hepáticas e queda de defesas (mielossupressão).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (15, N'interacoes', N'Anti-inflamatórios contínuos aumentam a toxicidade. Álcool deve ser evitado (hepatotoxicidade).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (15, N'advertencias', N'Exige hemograma e função hepática a cada 4-8 semanas. A dose é SEMANAL: erro de posologia para uso diário é grave e pode ser fatal.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (16, N'indicacao', N'Prevenção e tratamento de infecções bacterianas leves em pequenos cortes, escoriações e queimaduras superficiais.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (16, N'posologia', N'Aplicar uma camada fina sobre a região limpa e seca, 2 a 3 vezes ao dia, por no máximo 7 dias.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (16, N'contraindicacoes', N'Hipersensibilidade aos componentes, feridas extensas ou profundas (risco de absorção sistêmica).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (16, N'efeitos_adversos', N'Coceira local, vermelhidão e, raramente, dermatite de contato.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (16, N'interacoes', N'Sem interações relevantes pelo uso tópico em áreas pequenas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (16, N'advertencias', N'Uso prolongado favorece resistência bacteriana e flora fúngica. Sinais de infecção avançando (pus, febre, vermelhidão crescente) exigem avaliação médica.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (17, N'indicacao', N'Alívio da sensação de olho seco, areia e ardor associados a uso de telas, ar-condicionado e ambientes secos.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (17, N'posologia', N'1 a 2 gotas em cada olho, 3 a 4 vezes ao dia, ou conforme necessidade.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (17, N'contraindicacoes', N'Hipersensibilidade aos componentes.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (17, N'efeitos_adversos', N'Visão levemente embaçada por poucos segundos após a aplicação.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (17, N'interacoes', N'Se usar outros colírios, aguardar 5 minutos entre as aplicações.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (17, N'advertencias', N'Não tocar a ponta do frasco no olho. Descartar 30 dias após aberto. Dor ocular intensa, secreção ou alteração de visão exigem oftalmologista.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (18, N'indicacao', N'Auxílio no equilíbrio da flora intestinal durante e após uso de antibióticos e em quadros de desconforto intestinal funcional.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (18, N'posologia', N'1 sachê ao dia, dissolvido em água em temperatura ambiente (nunca quente), preferencialmente em jejum.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (18, N'contraindicacoes', N'Imunossuprimidos graves e pacientes com cateter venoso central (risco teórico de fungemia/bacteremia).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (18, N'efeitos_adversos', N'Leve distensão nos primeiros dias de uso.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (18, N'interacoes', N'Antibióticos podem inativar o probiótico: tomar com intervalo de pelo menos 2 horas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (18, N'advertencias', N'Conservar em geladeira. Diarreia com sangue, febre ou desidratação não deve ser tratada apenas com probiótico: procurar atendimento.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (19, N'indicacao', N'Tratamento de micoses superficiais de pele (tinhas, frieira entre os dedos).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (19, N'posologia', N'Aplicar uma vez ao dia na lesão e 2 cm ao redor, por 7 a 14 dias, mesmo após melhora da aparência.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (19, N'contraindicacoes', N'Hipersensibilidade ao componente. Não usar em olhos, boca ou mucosas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (19, N'efeitos_adversos', N'Ardor ou ressecamento passageiro no local da aplicação.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (19, N'interacoes', N'Sem interações relevantes pelo uso tópico.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (19, N'advertencias', N'Higiene e secagem cuidadosa da área são parte do tratamento. Falta de resposta em 2 semanas sugere outro diagnóstico: reavaliar.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (20, N'indicacao', N'Auxílio na fluidificação e eliminação do catarro em quadros respiratórios agudos.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (20, N'posologia', N'Adultos: 10 mL três vezes ao dia. Crianças acima de 6 anos: 5 mL três vezes ao dia.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (20, N'contraindicacoes', N'Crianças menores de 6 anos e hipersensibilidade ao componente.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (20, N'efeitos_adversos', N'Náusea e, raramente, vômito em doses altas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (20, N'interacoes', N'Não associar a antitussígenos (drogas que suprimem a tosse), pois o objetivo é justamente eliminar o catarro.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (20, N'advertencias', N'Hidratação adequada potencializa o efeito expectorante. Tosse com falta de ar, febre alta, sangue no catarro ou duração acima de 10 dias exige avaliação.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (21, N'indicacao', N'Alívio dos sintomas de insuficiência venosa crônica: sensação de peso, dor e inchaço nas pernas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (21, N'posologia', N'1 comprimido ao dia, junto ao almoço, por ciclos de 2 a 3 meses.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (21, N'contraindicacoes', N'Hipersensibilidade ao componente.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (21, N'efeitos_adversos', N'Desconforto gástrico leve e, raramente, dor de cabeça passageira.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (21, N'interacoes', N'Sem interações clinicamente relevantes conhecidas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (21, N'advertencias', N'Não substitui medidas como elevação das pernas, meias de compressão e atividade física. Inchaço súbito em uma perna só, com dor e calor, exigem avaliação urgente (suspeita de trombose).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (22, N'indicacao', N'Controle glicêmico no diabetes mellitus tipo 1 e tipo 2, conforme esquema prescrito.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (22, N'posologia', N'Aplicar por via subcutânea, em doses e horários individualizados pelo médico, geralmente 1 a 2 vezes ao dia. Homogeneizar suavemente rolando o frasco antes de aspirar.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (22, N'contraindicacoes', N'Episódios de hipoglicemia (só reaplicar após normalização da glicemia e reavaliação).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (22, N'efeitos_adversos', N'Hipoglicemia (suor frio, tremor, confusão), lipohipertrofia nos locais de aplicação e ganho de peso.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (22, N'interacoes', N'Álcool e atividade física intensa potencializam a hipoglicemia. Corticoides e diuréticos elevam a glicemia, exigindo reajuste.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (22, N'advertencias', N'Revezar os locais de aplicação. Manter lanche à mão. Frasco em uso pode ficar até 28 dias em temperatura ambiente; os demais, na geladeira (nunca no congelador).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (23, N'indicacao', N'Alívio de inflamações e coceiras de pele em dermatites de contato, eczema e picadas de inseto.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (23, N'posologia', N'Aplicar camada fina 1 a 2 vezes ao dia, por no máximo 7 dias consecutivos, salvo orientação médica.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (23, N'contraindicacoes', N'Infecções de pele não tratadas (fúngicas, bacterianas ou virais), acne rosácea e uso em face em crianças pequenas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (23, N'efeitos_adversos', N'Ressecamento local e, com uso prolongado, afinamento da pele (atrofia).', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (23, N'interacoes', N'Sem interações relevantes pelo uso tópico em pequenas áreas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (23, N'advertencias', N'Não usar em áreas extensas, oclusivas ou por tempo prolongado. Piora do quadro pode indicar infecção associada: suspender e procurar avaliação.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (24, N'indicacao', N'Profilaxia de enxaqueca de frequência alta e tratamento auxiliar da hipertensão arterial.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (24, N'posologia', N'40 mg uma vez ao dia, podendo ser ajustado a cada 2 semanas. Efeito profilático completo avaliado após 4 a 6 semanas.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (24, N'contraindicacoes', N'Asma ou DPOC com broncoespasmo, bradicardia importante, bloqueio cardíaco e descompensação cardíaca.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (24, N'efeitos_adversos', N'Cansaço, mãos e pés frios, bradicardia e sonhos vívidos.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (24, N'interacoes', N'Antagoniza bronchodilatadores como o Asmaplus. Verapamil-like elevam risco de bradicardia. Suspensão abrupta pode causar efeito rebote.', NULL);
INSERT INTO dbo.bula_chunk (medicamento_id, secao, conteudo, embedding) VALUES (24, N'advertencias', N'Nunca interromper de forma abrupta: reduzir gradualmente. Diabéticos devem saber que o betabloqueador pode mascarar sinais de hipoglicemia.', NULL);
